questionvariables.text:
/*finding the questions variables*/
const_1:rand(2)+2;
const_2:rand(5)+5;
const_3:rand(4)+const_1;
const_4:const_3+const_1;
quest_func:(const_1+const_2*%e^x)/(const_3-const_4*%e^x);

/*worked solution variables*/
sol1:x=(const_1+const_2*%e^y)/(const_3-const_4*%e^y);
sol2:x*(const_3-const_4*%e^y)=(const_1+const_2*%e^y);
sol3:x*const_3-const_4*%e^y*x=const_1+const_2*%e^y;
sol4:const_2*%e^y+const_4*%e^y*x=x*const_3-const_1;
sol5:%e^y*(const_2+const_4*x)=x*const_3-const_1;
sol6:%e^y=(x*const_3-const_1)/(const_2+const_4*x);
sol_y:log((x*const_3-const_1)/(const_2+const_4*x));
